import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"legame fra la crescenza/decrescenza e derivata prima","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/cg/cgac.md","filePath":"lezioni/c_analisi/cg/cgac.md"}`),a={name:`lezioni/c_analisi/cg/cgac.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="legame-fra-la-crescenza-decrescenza-e-derivata-prima" tabindex="-1">legame fra la crescenza/decrescenza e derivata prima <a class="header-anchor" href="#legame-fra-la-crescenza-decrescenza-e-derivata-prima" aria-label="Permalink to “legame fra la crescenza/decrescenza e derivata prima”">​</a></h1><p>Poiché la derivata corrisponde al coefficiente angolare della tangente, se la derivata è positiva significa che la tangente tende verso l&#39;alto quindi la curva dovrà essere crescente:</p><blockquote><p><strong>Regola:</strong></p><p class="text-purple">[se in un intervallo la derivata è positiva allora nell&#39;intervallo la funzione sarà crescente]</p><p class="text-purple">[se invece nell&#39;intervallo la derivata è negativa allora la funzione sarà decrescente]</p></blockquote><blockquote><p>Con le conoscenze che hai, se hai capito bene il concetto, dovresti riuscire a dimostrarlo, cioè a mostrare che se la derivata è maggiore di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> allora la funzione è crescente.</p><p><strong>Nota:</strong> fai attenzione che esercizi del genere sono piuttosto comuni agli esami.</p></blockquote>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};